    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        N = int(input[index])
        index += 1
        A = input[index]
        index += 1
        B = input[index]
        index += 1
        if A == B:
            results.append("0")
            continue
        steps = []
        for i in range(N):
            if A[i] != B[i]:
                found = False
                for j in range(i, N):
                    if B[j] == A[i]:
                        found = True
                        break
                if not found:
                    results.append("-1")
                    break
        else:
            used = [False] * N
            for i in range(N):
                if not used[i]:
                    current_char = B[i]
                    group = [i]
                    for j in range(i + 1, N):
                        if B[j] == current_char and not used[j]:
                            group.append(j)
                            used[j] = True
                    steps.append((current_char, group))
            operations = []
            for char, group in steps:
                min_char = min(A[i] for i in group)
                if min_char > char:
                    operations.append(group)
            results.append(str(len(operations)))
            for op in operations:
                results.append(f"{len(op)} {' '.join(map(str, op))}")
        if len(results) > 0 and results[-1] != "-1":
            results.append("")
    print("\n".join(results).strip())

main()
